ts
export type Range = { start: string; end: string };
export type Availability = Record<string, Range[]>;

const overlaps = (a: Range, b: Range) =>
  new Date(a.start) < new Date(b.end) && new Date(b.start) < new Date(a.end);

export function rankSlots(slots: Range[], availability: Availability) {
  const people = Object.keys(availability);
  return slots
    .map((slot) => {
      const free = people.filter((p) => !availability[p].some((b) => overlaps(slot, b)));
      const hour = new Date(slot.start).getHours();
      const penalty = hour < 9 || hour >= 17 ? 0.5 : 0;
      return { slot, free: free.length, score: free.length - penalty };
    })
    .sort((a, b) => b.score - a.score);
}


